changeSet.sql:
CREATE TABLE chats ( id UUID PRIMARY KEY, type VARCHAR(63) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL );
CREATE TABLE chat_members ( chat_id UUID NOT NULL, user_id UUID NOT NULL, joined_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY (chat_id, user_id), CONSTRAINT fk_chat_members_chat FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE );
CREATE INDEX idx_chat_members_user_id ON chat_members(user_id);
